import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>JPG 统治网络三十年了。WebP 是谷歌为取代它而打造的挑战者，论纯效率，WebP 赢了。论兼容性，JPG 仍是王。</p>\n<p>两者之间的选择，不是理论上哪种格式更好。而是图片会住在哪里、谁会看它、这张图片最重要的是什么。</p>\n<p>这篇对比覆盖文件大小、画质、透明背景和支持情况，让你凭事实、而不是凭风尚做决定。</p>\n<h2 id=\"jpg-at-a-glance\">JPG 一览</h2>\n<p>JPG 是 1992 年为照片设计的有损格式。它丢弃细节来缩小文件，这份工作做得足够好，撑过了三十年。</p>\n<p>世界上每台设备、浏览器、打印机、上传表格都能打开 JPG。没有主流系统会拒收它，从来没有过。</p>\n<p>JPG 只支持 8 位颜色，没有透明背景。JPG 就是一矩形扁平像素，简单、可靠，同时也有局限。</p>\n<p>格式的年龄体现在效率上。现代格式能以更少的字节装下同样的画质，但 JPG 的通用性让它依然重要。</p>\n<h2 id=\"webp-at-a-glance\">WebP 一览</h2>\n<p>WebP 是谷歌的现代格式，2010 年发布。它同时支持有损和无损压缩、透明背景，甚至动画，集于一身。</p>\n<p>同等视觉画质下，有损 WebP 通常比 JPG 小 25% 到 35%。无损 WebP 比 PNG 小的幅度也差不多。</p>\n<p>WebP 还能处理透明背景，JPG 完全做不到。WebP 标志可以是透明的，JPG 标志永远有实心背景。</p>\n<p>这种格式现在所有主流浏览器都支持。Chrome、Edge、Firefox、Safari、Opera 都原生显示 WebP，覆盖了几乎所有网络流量。</p>\n<h2 id=\"file-size-compared\">文件大小：WebP 明显胜出</h2>\n<p>一张 1MB 的 JPG 照片，同等视觉画质下变成 650KB 到 750KB 的 WebP。25% 到 35% 的节省在大多数照片上都很稳定。</p>\n<p>简单图片省得更多。纯色区域多的截图转成 WebP 能缩小一半，因为现代编码器高效处理纯色。</p>\n<p>细节图片省得更少。纹理无穷无尽的繁忙风景留给改善的空间更小，不过 WebP 依然明显胜出。</p>\n<p>整个网站加起来，节省很可观。二十张图片的页面可能从 10MB 降到 7MB，加载时间上的改善看得见。</p>\n<h2 id=\"quality-compared\">画质：WebP 小胜</h2>\n<p>同样文件大小下，WebP 看起来比 JPG 好。它的现代压缩比老旧的 JPG 标准更忠实地保留边缘和纹理。</p>\n<p>同样视觉画质下，WebP 更小。无论怎么衡量，WebP 都是照片更高效的格式。</p>\n<p>高画质下差别很微妙。90% 的 JPG 和 85% 的 WebP 大多数人看起来一模一样，虽然 WebP 文件更小。</p>\n<p>低画质下差别拉大。60% 的 JPG 出现块状痕迹，同样大小的 WebP 却依然干净、自然。</p>\n<h2 id=\"transparency-compared\">透明背景：WebP 完胜</h2>\n<p>JPG 完全存不了透明。任何透明区域都必须填上实心颜色，彩色背景上的标志周围会出现显眼的框。</p>\n<p>WebP 支持完整透明，包括柔和边缘和阴影的半透明。WebP 标志干净地落在任何背景上，和 PNG 一样。</p>\n<p>这让 WebP 成为网上真正的 PNG 替代品，不只是 JPG 的替代品。标志、图标、贴纸用 WebP 都行，文件还比 PNG 小。</p>\n<p>任何需要透明的图片，JPG 根本不是选项。比较在 WebP 和 PNG 之间进行，体积上 WebP 通常赢。</p>\n<h2 id=\"browser-support-compared\">浏览器支持：JPG 赢，WebP 在追赶</h2>\n<p>JPG 在有史以来做的每个浏览器里都能用，包括 Internet Explorer。再老的软件，也没有访客看不到 JPG。</p>\n<p>WebP 在所有现代浏览器里都能用。Chrome、Edge、Firefox、Safari 14 及以后版本、Opera 都支持，覆盖了绝大多数流量。</p>\n<p>差距现在已经很小。Safari 在 2020 年加入了支持，剩下不支持的浏览器是用量可以忽略的老版本。</p>\n<p>极少数用古老浏览器的访客，给他们提供 JPG 备用。HTML 里的 picture 元素能让你先提供 WebP、再提供 JPG，每个人都能看到图片。</p>\n<h2 id=\"other-support\">浏览器之外的支持</h2>\n<p>邮件客户端情况不一。有的显示 WebP，有的显示不了，所以邮件里的图片用 JPG 依然是安全的选择。</p>\n<p>打印机和照片冲印店大多要 JPG 或 PNG。发给打印店的 WebP 文件可能被拒收，打印工作转 JPG 就好。</p>\n<p>桌面修图软件正在追赶。Photoshop 现在支持 WebP，但很多老修图软件不支持，编辑流程里 JPG 依然是更安全的选择。</p>\n<p>社交媒体平台反正会把上传内容转成自己的格式，源格式在那里不那么重要。上传 JPG 或 WebP，平台处理剩下的事。</p>\n<h2 id=\"when-to-use-jpg\">什么时候用 JPG</h2>\n<p>目的地不明时用 JPG。表格、客户、打印机、邮件收件人永远接受 JPG，WebP 可能会被拒收。</p>\n<p>邮件附件用 JPG。邮件客户端显示 JPG 很可靠，WebP 在邮件里的支持在各个应用里还不一致。</p>\n<p>打印工作用 JPG。打印店要 JPG 或 PNG，WebP 在纸上只增加兼容风险，没有任何好处。</p>\n<p>网站上的备用格式用 JPG。现代浏览器提供 WebP、老浏览器提供 JPG，每个访客都能看到图片。</p>\n<h2 id=\"when-to-use-webp\">什么时候用 WebP</h2>\n<p>网站图片用 WebP。更小的文件让页面加载更快，访客体验和搜索排名都更好。</p>\n<p>网店的产品照片用 WebP。几百张图片的目录，每张小 30%，加载快得多。</p>\n<p>博客图片和截图用 WebP。同样大小下文字比 JPG 更锐利，页面感觉明显更快。</p>\n<p>网上的标志和图标用 WebP。透明能用，文件比 PNG 小，每个现代浏览器都能显示。</p>\n<h2 id=\"converting-between-them\">JPG 与 WebP 之间转换</h2>\n<p>JPG 转 WebP 很容易，80% 画质下也很安全。照片保持尺寸、看起来一样，文件缩小三分之一。</p>\n<p>WebP 转 JPG 同样容易，用<a href=\"/zh/webp-zhuan-jpg/\">WebP 转 JPG 工具</a>就行。JPG 更大，但哪里都能打开，这正是转换的目的。</p>\n<p>永远从手头最好的原文件转。JPG 转 WebP、再转回 JPG，每步都会损失一点画质，所以要避免来回转换。</p>\n<p>转成 WebP 后留着 JPG 原文件。目的地拒收 WebP 时，JPG 已经准备好上传，不用重新转换。</p>\n<h2 id=\"core-web-vitals\">WebP 与核心网页指标</h2>\n<p>谷歌用核心网页指标测量页面速度，图片大小是主要因素。大图片会拖慢最大内容绘制，也就是主要内容出现的时间。</p>\n<p>网站图片从 JPG 换成 WebP，常常能明显改善这个测量。四秒加载的页面可能变成三秒，访客能感觉到。</p>\n<p>更小的图片也用更少的移动数据。慢速连接上的访客马上就能感觉到差别，在快速页面上停留更久。</p>\n<p>搜索排名反映了这一点。谷歌说过页面速度影响排名，所以 WebP 图片的快速网站有小而真实的优势。</p>\n<h2 id=\"verdict\">结论：哪种格式赢了？</h2>\n<p>效率、画质、功能上，WebP 赢了。它更小、更锐利、能力更强，纯技术上是更好的格式。</p>\n<p>兼容性和简单性上，JPG 赢了。它哪里都能打开，每个系统都理解它，永远不会用拒收给你意外。</p>\n<p>网上用 WebP，加 JPG 备用。其他地方用 JPG。这套组合兼得两种格式之长、避开两者之短。</p>\n<p>未来属于 WebP 和它的后继者，但现在仍需要 JPG。各用其所长，两者之间自由转换。</p>\n<h2 id=\"jpg-webp-email\">邮件里的 JPG 与 WebP</h2>\n<p>邮件是 JPG 依然明显胜出的地方。邮件客户端显示 JPG 很可靠，WebP 支持却不一致，邮件里出现破损图片看起来很不专业。</p>\n<p>带 WebP 图片的简报可能让部分订阅者看到破损图标。同样简报用 JPG 图片，每个人都显示正确，这就是邮件的目的。</p>\n<p>邮件附件用 JPG 也是安全的选择。文件小到能发送，每台设备上的每个客户端不用特殊软件都能打开。</p>\n<p>WebP 在邮件里还没有位置。在客户端一致采用它之前，JPG 依然是简报、附件和邮件签名的格式。</p>\n<p>发送前在几个邮件客户端里测试每份简报。在 Gmail、Outlook、Apple Mail 里快速测试，能在订阅者看到之前发现破损图片。</p>\n<h2 id=\"jpg-webp-social\">社交媒体上的 JPG 与 WebP</h2>\n<p>社交媒体平台会把上传内容转成自己的格式，源格式不如画质重要。高画质输入不管什么格式，结果都更好。</p>\n<p>照片帖子上传高画质 JPG。平台反正会压缩它，JPG 输入是所有平台上最兼容的起点。</p>\n<p>带文字的图形上传 PNG 或高画质 WebP。文字在平台压缩后保持更锐利，公告图形尤其需要这一点。</p>\n<p>上传前检查平台偏好的尺寸。Instagram、Facebook、X 各有理想尺寸，尺寸合适比格式更重要。</p>\n<p>上传后下载平台上的版本检查一下。快速看一眼已发布的帖子，确认图片在平台处理后依然完好。</p>\n<h2 id=\"jpg-webp-print\">打印时的 JPG 与 WebP</h2>\n<p>打印店要 JPG 或 PNG，打印工作里 WebP 没有位置。发给打印机的 WebP 文件可能直接被拒，或者印出错误的颜色。</p>\n<p>打印照片时，90% 画质或更高的 JPG 是标准。照片印出来干净，文件可控，打印店的工作流程原生处理它。</p>\n<p>打印带文字的文档时，PNG 比 JPG 或 WebP 都好。无损格式让每个字母边缘在纸上都清晰。</p>\n<p>发文件前问问打印店的偏好。大多数会说照片用 JPG、图形用 PNG，照着他们的偏好做能避免白跑一趟。</p>\n<p>重要任务先印一张测试。先印一张小的，确认颜色和锐利度，再决定大订单。</p>\n<h2 id=\"jpg-webp-archiving\">存档时的 JPG 与 WebP</h2>\n<p>存档需要五十年后还能打开的格式，JPG 是更安全的选择。它三十岁了，每个做出来的系统都支持它，WebP 还年轻。</p>\n<p>WebP 有一天可能成为存档标准，但那一天还没到。WebP 存档依赖未来软件支持这种格式，很可能支持，但不确定。</p>\n<p>原稿上，两种格式都不理想。无损 PNG 或 TIFF 原稿能精确保留每个像素，JPG 和有损 WebP 都会永久丢弃细节。</p>\n<p>原稿存 PNG，交付副本存 WebP 或 JPG。这套分工给你完美的存档和快速的交付，两边都不妥协。</p>\n<p>每隔几年检查一次存档。格式会变，以过时格式存的原稿，可能要在旧格式彻底读不出来之前迁移。</p>\n<h2 id=\"format-landscape-five-years\">五年后的格式格局</h2>\n<p>五年后，WebP 很可能像今天的 JPG 一样通用。浏览器已经支持它，操作系统正在追赶，剩下的差距正在缩小。</p>\n<p>AVIF 可能在同一时期超过 WebP，因为它效率更高。看重速度的网站会采用 AVIF，WebP 变成备用。</p>\n<p>JPG 不会消失。它深深嵌入每个系统，几十年里都会是通用备用，就像今天一样。</p>\n<p>对网站所有者来说，策略很清楚：提供最新格式，加 JPG 备用。这个办法今天管用，格式变化时还会继续管用。</p>\n<p>对其他人来说，建议更简单：文件打不开时，转成 JPG。这个建议三十年前管用，三十年后还会管用。</p>\n<h2 id=\"jpg-webp-video-thumbnails\">视频缩略图的 JPG 与 WebP</h2>\n<p>视频缩略图是必须瞬间抓住注意力的小图片。85% 画质的 JPG 缩略图锐利、小巧，和每个平台都兼容。</p>\n<p>WebP 缩略图更小，一个页面显示几十张时这一点很重要。五十张 WebP 缩略图的视频列表页，比同样页面的 JPG 加载快得多。</p>\n<p>带文字的缩略图，比如标题叠加，85% 的 WebP 比 JPG 更能让字母保持锐利。文字是缩略图的内容，它的锐利度很重要。</p>\n<p>上传前检查平台的缩略图规则。YouTube、Vimeo 和其他平台各有偏好的尺寸，尺寸合适比格式更重要。</p>\n<p>按真实显示尺寸测试缩略图，别放大了看。全尺寸下看得见的瑕疵，缩略图以 200 像素宽显示时根本不重要。</p>\n<p>现在就想转？打开<a href=\"/zh/jpg-zhuan-webp/\">JPG 转 WebP 工具</a>缩小照片，或者打开<a href=\"/zh/webp-zhuan-jpg/\">WebP 转 JPG 工具</a>让它们重新通用。分步操作请读<a href=\"/zh/blog/ruhe-ba-jpg-zhuancheng-webp/\">如何把 JPG 转换成 WebP</a>，一般背景请看<a href=\"/zh/blog/jpg-zhuan-webp-wanquan-zhinan/\">JPG 转 WebP 完全指南</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"网站上用 WebP 真的比 JPG 好吗？","answer":"大多数网站图片是的。同等视觉画质下 WebP 小 25% 到 35%，页面加载更快，核心网页指标更好。唯一的顾虑是很老浏览器的兼容性，JPG 备用能解决。现代网站，WebP 是正确的选择。"},{"question":"邮件里能用 WebP 图片吗？","answer":"不可靠。有些邮件客户端显示 WebP，很多显示不了，邮件里出现破损图片看起来很不专业。邮件附件和简报用 JPG，每个客户端都能显示。WebP 留给网页，那里浏览器支持是一致的。"},{"question":"WebP 像 PNG 一样支持透明背景吗？","answer":"支持。WebP 支持完整透明，包括柔和边缘和阴影的半透明，和 PNG 一样。这让它成为网上真正的 PNG 替代品，文件通常小得多。JPG 完全存不了透明。"},{"question":"JPG 转 WebP 会损害照片画质吗？","answer":"设置得当的话，损害微乎其微。80% 画质的 WebP 通常看起来和原 JPG 一模一样，文件还更小。只有放大细看，或把画质设得很低时才看得出损失。网上用，这笔买卖几乎总是划算的。"},{"question":"网站上用 WebP 需要 JPG 备用吗？","answer":"是好习惯，虽然不像以前那么必要了。所有现代浏览器都支持 WebP，但 JPG 备用代价很小，能覆盖极少数用老浏览器的访客。HTML 里的 picture 元素让同时提供两种格式变得简单。"},{"question":"打印照片时 WebP 比 JPG 好吗？","answer":"不好。打印机和打印店要 JPG 或 PNG，WebP 只增加兼容风险，在纸上没有任何好处。打印工作用 90% 画质或更高的 JPG。WebP 是网络格式，图片一离开屏幕，它的优势就消失了。"}];
